item.content:encoded:
body.elementor-page {
    background: #f3f3f3;
}

#dokan-seller-listing-wrap ul.dokan-seller-wrap {
    display: flex;
    flex-flow: row wrap;
}

.pagination-wrap ul.pagination {
    margin: 20px 15px;
}

@media(min-width: 768px) {
	.woocommerce ul.products {
    display: flex;
    flex-flow: row wrap;
}
}

